#!/usr/bin/env bash
# High-load blind cells (TASK86): every lifecycle of ORDER_HI.json, streaming,
# in the preregistered order. Same procedure as run_main.sh (directive 05 §2.4).
#
#   run_hiload.sh <RUN_DIR_ABS>
#
# After each lifecycle only its validity is checked (mt_check.py, no outcome
# metric is printed). An INVALID lifecycle is rerun once with the same plan
# under the tag "<tag>.retry1"; a second INVALID is left as it is. Resumable:
# a tag with a done marker and a check record is skipped by run_multiturn.sh.
# Do not edit this file, run_multiturn.sh or the runner while it runs
# (KNOWN_PITFALLS 5).
set -uo pipefail
RUN="$1"
REPO=/home/rebel/continuum-npu
case "$RUN" in /*) ;; *) echo "RUN must be absolute"; exit 64 ;; esac
mkdir -p "$RUN"
S3="$REPO/experiments/npu/stage3"
PLANS="$S3/plans/main"
declare -A ART=(
  [BASE]="$REPO/models/Qwen3-4B-rbln-b8-s8192-d4-mb"
  [BATCHONLY]="$REPO/models/Qwen3-4B-rbln-b16-s8192-d4-batchonly"
  [TUNED]="$REPO/models/Qwen3-4B-rbln-b16-s8192-d4-mb16"
)
for c in "${!ART[@]}"; do [ -f "${ART[$c]}/rbln_config.json" ] || { echo "missing artifact $c"; exit 2; }; done

git -C "$REPO" rev-parse HEAD >> "$RUN/git-head.txt"
git -C "$REPO" status --porcelain >> "$RUN/git-status.txt"
[ -f "$RUN/measurement-start.txt" ] || date -Is > "$RUN/measurement-start.txt"
rbln-stat > "$RUN/rbln-stat-before.$(date +%s).txt" 2>&1
bash "$REPO/patches/vllm_rbln-0.11.1/apply.sh" status > "$RUN/patch-before.$(date +%s).txt" 2>&1

mapfile -t ITEMS < <(python3 -c "
import json
for e in json.load(open('$PLANS/ORDER_HI.json'))['order']:
    print(e['seq'], e['tag'], e['config'], e['plan_id'])")

one() {  # seq tag config plan_id
  local SEQ="$1" TAG="$2" CFG="$3" PID="$4"
  echo "=== [$SEQ] $TAG $(date -Is)"
  bash "$S3/run_multiturn.sh" "$RUN" "$TAG" "${ART[$CFG]}" "$PLANS/$PID.json" stream
  env -u PYTHONPATH python3 "$S3/mt_check.py" --run "$RUN" --tag "$TAG" --config "$CFG" \
    --plan-id "$PID" > "$RUN/check.$TAG.json" 2> "$RUN/check.$TAG.err"
  local RC=$?
  cat "$RUN/check.$TAG.json" >> "$RUN/checks.jsonl"
  if [ "$RC" -eq 0 ]; then echo "[$SEQ] $TAG VALID"; else echo "[$SEQ] $TAG INVALID"; fi
  return $RC
}

for item in "${ITEMS[@]}"; do
  set -- $item
  SEQ="$1"; TAG="$2"; CFG="$3"; PID="$4"
  if [ -f "$RUN/check.$TAG.json" ] && [ -f "$RUN/done.$TAG" ] && \
     python3 -c "import json,sys; sys.exit(0 if json.load(open('$RUN/check.$TAG.json'))['valid'] else 1)"; then
    echo "[$SEQ] $TAG already valid, skipping"; continue
  fi
  if [ -f "$RUN/check.$TAG.json" ] && [ -f "$RUN/check.$TAG.retry1.json" ]; then
    echo "[$SEQ] $TAG already retried, skipping"; continue
  fi
  if [ ! -f "$RUN/check.$TAG.json" ]; then
    one "$SEQ" "$TAG" "$CFG" "$PID" && continue
  fi
  one "$SEQ" "$TAG.retry1" "$CFG" "$PID"
done

date -Is > "$RUN/measurement-end.txt"
rbln-stat > "$RUN/rbln-stat-after.txt" 2>&1
bash "$REPO/patches/vllm_rbln-0.11.1/apply.sh" status > "$RUN/patch-after.txt" 2>&1
echo "MAIN DONE"
